export const CollisionLayers = {
  BALL: 0x0001,
  COURSE: 0x0002,
  OBSTACLE: 0x0004,
  SENSOR: 0x0008,
} as const;

export function collisionGroups(membership: number, filter: number): number {
  return ((membership & 0xffff) << 16) | (filter & 0xffff);
}

export const BALL_COLLISION_GROUPS = collisionGroups(
  CollisionLayers.BALL,
  CollisionLayers.COURSE | CollisionLayers.OBSTACLE | CollisionLayers.SENSOR,
);
