import type { Vec3 } from '../contracts/math';

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function magnitude(v: Vec3): number {
  return Math.hypot(v.x, v.y, v.z);
}

export function normalizeHorizontal(direction: Vec3): Vec3 | null {
  const length = Math.hypot(direction.x, direction.z);
  if (length < 1e-8) return null;
  return { x: direction.x / length, y: 0, z: direction.z / length };
}

export function shotImpulseFromCharge(
  charge: number,
  minPower: number,
  maxPower: number,
  exponent: number,
): number {
  const t = clamp(charge, 0, 1);
  return minPower + (maxPower - minPower) * Math.pow(t, exponent);
}

export function cappedVelocity(v: Vec3, maxSpeed: number): Vec3 {
  const speed = magnitude(v);
  if (speed <= maxSpeed || speed < 1e-8) return { ...v };
  const scale = maxSpeed / speed;
  return { x: v.x * scale, y: v.y * scale, z: v.z * scale };
}

export function shouldSleep(speed: number, stopThreshold: number, quietSeconds: number, sleepDelaySeconds: number): boolean {
  return speed <= stopThreshold && quietSeconds >= sleepDelaySeconds;
}
