import RAPIER from '@dimforge/rapier3d-compat';
import { GAME_CONFIG } from '../config/GameConfig';
import type { Vec3 } from '../contracts/math';
import { BALL_COLLISION_GROUPS } from './CollisionLayers';
import { cappedVelocity, magnitude, normalizeHorizontal, shotImpulseFromCharge, shouldSleep } from './helpers';
import type { PhysicsWorld } from './PhysicsWorld';

export interface GolfBallPhysicsOptions {
  radius?: number;
  mass?: number;
  friction?: number;
  restitution?: number;
  linearDamping?: number;
  angularDamping?: number;
  rollingResistance?: number;
  airResistance?: number;
}

export interface ShotResult {
  accepted: boolean;
  impulse: number;
}

export class GolfBallPhysics {
  readonly body: RAPIER.RigidBody;
  readonly collider: RAPIER.Collider;
  lastSafePosition: Vec3;
  private quietSeconds = 0;
  private readonly rollingResistance: number;
  private readonly airResistance: number;

  constructor(physics: PhysicsWorld, spawn: Vec3, options: GolfBallPhysicsOptions = {}) {
    const config = GAME_CONFIG.physics;
    const radius = options.radius ?? config.ballRadius;
    const mass = options.mass ?? config.ballMass;
    this.rollingResistance = options.rollingResistance ?? 0.32;
    this.airResistance = options.airResistance ?? 0.018;
    this.body = physics.world.createRigidBody(
      RAPIER.RigidBodyDesc.dynamic()
        .setTranslation(spawn.x, spawn.y, spawn.z)
        .setLinearDamping(options.linearDamping ?? 0.08)
        .setAngularDamping(options.angularDamping ?? 0.22)
        .setCcdEnabled(true),
    );
    this.collider = physics.world.createCollider(
      RAPIER.ColliderDesc.ball(radius)
        .setMass(mass)
        .setFriction(options.friction ?? 0.55)
        .setRestitution(options.restitution ?? 0.32)
        .setCollisionGroups(BALL_COLLISION_GROUPS),
      this.body,
    );
    this.lastSafePosition = { ...spawn };
  }

  get position(): Vec3 {
    const p = this.body.translation();
    return { x: p.x, y: p.y, z: p.z };
  }

  get velocity(): Vec3 {
    const v = this.body.linvel();
    return { x: v.x, y: v.y, z: v.z };
  }

  get speed(): number {
    return magnitude(this.velocity);
  }

  get canShoot(): boolean {
    return this.body.isSleeping() || this.speed <= GAME_CONFIG.physics.ballStopThreshold;
  }

  applyShot(direction: Vec3, charge: number): ShotResult {
    if (!this.canShoot) return { accepted: false, impulse: 0 };
    const normalized = normalizeHorizontal(direction);
    if (!normalized) return { accepted: false, impulse: 0 };
    const cfg = GAME_CONFIG.physics;
    const impulse = shotImpulseFromCharge(charge, cfg.minShotPower, cfg.maxShotPower, cfg.powerExponent);
    this.body.wakeUp();
    this.body.applyImpulse({ x: normalized.x * impulse, y: 0, z: normalized.z * impulse }, true);
    this.limitSpeed();
    this.quietSeconds = 0;
    return { accepted: true, impulse };
  }

  update(dt: number): void {
    const cfg = GAME_CONFIG.physics;
    const velocity = this.velocity;
    const speed = magnitude(velocity);
    if (speed > cfg.ballStopThreshold) {
      this.quietSeconds = 0;
      const horizontalSpeed = Math.hypot(velocity.x, velocity.z);
      if (horizontalSpeed > 1e-6) {
        const rolling = Math.max(0, 1 - this.rollingResistance * dt);
        const air = 1 / (1 + this.airResistance * speed * dt);
        this.body.setLinvel({ x: velocity.x * rolling * air, y: velocity.y * air, z: velocity.z * rolling * air }, true);
      }
      this.limitSpeed();
      return;
    }
    this.quietSeconds += dt;
    if (shouldSleep(speed, cfg.ballStopThreshold, this.quietSeconds, cfg.sleepDelaySeconds)) {
      this.body.setLinvel({ x: 0, y: 0, z: 0 }, false);
      this.body.setAngvel({ x: 0, y: 0, z: 0 }, false);
      this.body.sleep();
    }
  }

  markSafePosition(position: Vec3 = this.position): void {
    this.lastSafePosition = { ...position };
  }

  reset(position: Vec3 = this.lastSafePosition): void {
    this.body.setTranslation(position, false);
    this.body.setLinvel({ x: 0, y: 0, z: 0 }, false);
    this.body.setAngvel({ x: 0, y: 0, z: 0 }, false);
    this.body.resetForces(false);
    this.body.resetTorques(false);
    this.quietSeconds = 0;
    this.body.sleep();
  }

  private limitSpeed(): void {
    const limited = cappedVelocity(this.velocity, GAME_CONFIG.physics.maxBallSpeed);
    const current = this.velocity;
    if (limited.x !== current.x || limited.y !== current.y || limited.z !== current.z) {
      this.body.setLinvel(limited, true);
    }
  }
}
