import test from 'node:test';
import assert from 'node:assert/strict';
import { cappedVelocity, magnitude, shotImpulseFromCharge, shouldSleep } from '../../src/physics/helpers.js';

test('shot power clamps and follows configured curve endpoints', () => {
  assert.equal(shotImpulseFromCharge(-1, 0.6, 14, 1.65), 0.6);
  assert.equal(shotImpulseFromCharge(1, 0.6, 14, 1.65), 14);
  const half = shotImpulseFromCharge(0.5, 0.6, 14, 1.65);
  assert.ok(half > 0.6 && half < 7.3);
});

test('speed cap preserves direction and limits magnitude', () => {
  const capped = cappedVelocity({ x: 30, y: 0, z: 40 }, 20);
  assert.ok(Math.abs(magnitude(capped) - 20) < 1e-9);
  assert.ok(Math.abs(capped.x / capped.z - 0.75) < 1e-9);
});

test('sleep requires both low speed and sufficient quiet time', () => {
  assert.equal(shouldSleep(0.05, 0.075, 0.7, 0.6), true);
  assert.equal(shouldSleep(0.08, 0.075, 1, 0.6), false);
  assert.equal(shouldSleep(0.05, 0.075, 0.3, 0.6), false);
});
EOF
