import test from 'node:test';
import assert from 'node:assert/strict';
import RAPIER from '@dimforge/rapier3d-compat';
import { GolfBallPhysics } from '../../src/physics/GolfBallPhysics.js';
import { PhysicsWorld } from '../../src/physics/PhysicsWorld.js';

test('ball shot is accepted at rest and safe reset clears motion', async () => {
  await RAPIER.init();
  const physics = new PhysicsWorld();
  const ball = new GolfBallPhysics(physics, { x: 1, y: 2, z: 3 });
  const shot = ball.applyShot({ x: 1, y: 0, z: 0 }, 1);
  assert.equal(shot.accepted, true);
  assert.ok(shot.impulse > 0);
  ball.markSafePosition({ x: 4, y: 5, z: 6 });
  ball.reset();
  assert.deepEqual(ball.position, { x: 4, y: 5, z: 6 });
  assert.equal(ball.speed, 0);
  assert.equal(ball.body.isSleeping(), true);
  physics.dispose();
});
